# Compute gap density per column in both AA and 3Di MSAs
python3 << 'PYEOF'
import statistics

def col_gap_dist(path):
    seqs = []
    cur, buf = None, []
    with open(path) as fh:
        for line in fh:
            if line.startswith(">"):
                if cur: seqs.append("".join(buf))
                cur=line; buf=[]
            else: buf.append(line.strip())
    if cur: seqs.append("".join(buf))
    n = len(seqs); L = len(seqs[0])
    gap_frac = [sum(1 for s in seqs if s[i] == '-')/n for i in range(L)]
    return n, L, gap_frac

for path in ["phylo_q1/reps_aa.fa", "phylo_q1/reps_3di.fa"]:
    n, L, gf = col_gap_dist(path)
    print(f"--- {path} ({n} seqs × {L} cols) ---")
    cuts = [0.05, 0.10, 0.20, 0.35, 0.50, 0.65, 0.80, 0.90]
    for c in cuts:
        n_kept = sum(1 for x in gf if x <= c)
        print(f"  ≤{int(c*100)}% gap cols kept (= -gt {1-c:.2f}): {n_kept}")
