for jid in job_ids:
    # Try common Galaxy cancel endpoint forms.
    for method, endpoint, payload in [
        ('PUT', f'/api/jobs/{jid}', {'state':'deleted'}),
        ('DELETE', f'/api/jobs/{jid}', None),
        ('PUT', f'/api/jobs/{jid}/cancel', {}),
    ]:
