            if method=='PUT':
                r=requests.put(url+endpoint, headers=headers, json=payload, timeout=30)
            elif method=='DELETE':
                r=requests.delete(url+endpoint, headers=headers, timeout=30)
            print(method, endpoint, '->', r.status_code, r.text[:500])
            if r.status_code in (200,202,204):
