import os, json, requests
url=os.environ['GALAXY_URL'].rstrip('/'); key=os.environ['GALAXY_API_KEY']
headers={'x-api-key':key,'Content-Type':'application/json'}

shell = r'''set -euo pipefail
threads="$(inputs.threads)"
mkdir -p prostt5_weights tmp
cp "$(inputs.prostt5_model.path)" prostt5_weights/prostt5-f16.gguf

echo "Foldseek version:" > foldseek.log
foldseek version >> foldseek.log 2>&1 || true
echo "Threads: $threads" >> foldseek.log
echo "GPU flag: --gpu 1" >> foldseek.log
echo "Summary generator: awk/sort; no Python dependency" >> foldseek.log

foldseek easy-cluster \
  "$(inputs.seqs.path)" \
  vir_struct_cluster \
  tmp \
  --prostt5-model prostt5_weights \
  -c "$(inputs.coverage)" \
  -e "$(inputs.evalue)" \
  --alignment-type "$(inputs.alignment_type)" \
  --gpu 1 \
  --threads "$threads" >> foldseek.log 2>&1

awk -F '\t' '
function genome(pid) {
    if (pid ~ /^PVP01/) return "PvP01";
    if (pid ~ /^PVPAM/) return "PvPAM";
    if (pid ~ /PvW1/ || pid ~ /PVW1/ || pid ~ /PVPVW/ || pid ~ /PVPV/) return "PvW1";
    return "unknown";
}
{
    rep=$1; member=$2; key=rep SUBSEP member;
    if (!(key in seen)) {
        seen[key]=1;
        size[rep]++;
        g=genome(member);
        count[rep,g]++;
    }
}
END {
    for (rep in size) {
        printf "%d\t%s\t%d\t%d\t%d\t%d\t%d\n", -size[rep], rep, size[rep]+0, count[rep,"PvP01"]+0, count[rep,"PvW1"]+0, count[rep,"PvPAM"]+0, count[rep,"unknown"]+0;
    }
}' vir_struct_cluster_cluster.tsv \
  | sort -k1,1n -k2,2 \
  | awk -F '\t' 'BEGIN { OFS="\t"; print "FS_cluster", "rep_id", "size", "PvP01", "PvW1", "PvPAM", "unknown" } { printf "FS_%03d\t%s\t%d\t%d\t%d\t%d\t%d\n", NR, $2, $3, $4, $5, $6, $7 }' \
  > foldseek_clusters_summary.tsv

ls -lh vir_struct_cluster* foldseek_clusters_summary.tsv >> foldseek.log 2>&1
'''

