    {"name":"alignment_type","type":"integer","label":"Foldseek alignment type","value":2},
    {"name":"threads","type":"integer","label":"Threads","value":32}
  ],
  "outputs":[
    {"name":"cluster_tsv","type":"data","format":"tabular","label":"Foldseek cluster assignments","from_work_dir":"vir_struct_cluster_cluster.tsv"},
    {"name":"rep_seq","type":"data","format":"fasta","label":"Foldseek representative sequences","from_work_dir":"vir_struct_cluster_rep_seq.fasta"},
    {"name":"all_seqs","type":"data","format":"fasta","label":"Foldseek clustered sequences FASTA","from_work_dir":"vir_struct_cluster_all_seqs.fasta"},
    {"name":"summary_tsv","type":"data","format":"tabular","label":"Foldseek cluster summary","from_work_dir":"foldseek_clusters_summary.tsv"},
    {"name":"log","type":"data","format":"txt","label":"Foldseek clustering log","from_work_dir":"foldseek.log"}
  ],
  "help":{"format":"markdown","content":"Runs Foldseek `easy-cluster` with a supplied ProstT5 GGUF model and explicit `--gpu 1`. Container identifier: `quay.io/biocontainers/foldseek:10.941cd33`. The post-processing summary uses awk/sort instead of Python because this Foldseek image does not include Python."},
